func lsfFromValueMaybeSignature(v LawSpecValue) lsfMaybe[*lsfSignature] {
	tag, fields := lsfData(v)
	if tag == "Maybe::Present" {
		return lsfPresent[*lsfSignature](lsfFromValueSignature(fields[0]))
	}
	return lsfAbsent[*lsfSignature]()
}

func lsfFromValueComplexity(v LawSpecValue) *lsfComplexity {
	tag, fields := lsfData(v)
	switch tag {
	case "assayxport.contract::type::Complexity::Complexity":
		return &lsfComplexity{lsfFromValueMaybeText(fields[0]), lsfFromValueMaybeText(fields[1]), lsfFromValueComplexityMethod(fields[2])}
	}
	panic("expected Complexity, found " + tag)
}

func lsfFromValueTypeParam(v LawSpecValue) *lsfTypeParam {
	tag, fields := lsfData(v)
	switch tag {
	case "assayxport.contract::type::TypeParam::TypeParam":
		return &lsfTypeParam{lsfFromValueText(fields[0]), lsfFromValueText(fields[1])}
	}
	panic("expected TypeParam, found " + tag)
}

func lsfFromValueGroupDetails(v LawSpecValue) *lsfGroupDetails {
	tag, fields := lsfData(v)
	switch tag {
	case "lawspec::structural::record::0da2e14ca58604b3fe86a7b98c18b8fc5d80c0dfa11517770dd5008b6ef149d5::Record":
		return &lsfGroupDetails{lsfFromValueListArm(fields[0]), lsfFromValueListInner(fields[1]), lsfFromValueBool(fields[2])}
	}
	panic("expected Record0da2e14ca58604b3fe86a7b98c18b8fc5d80c0dfa11517770dd5008b6ef149d5, found " + tag)
}

func lsfFromNativeMaybeSignature(n LawSpecMaybe[Signature]) lsfMaybe[*lsfSignature] {
	if v, ok := n.Value(); ok {
		return lsfPresent[*lsfSignature](lsfFromNativeSignature(v))
	}
	return lsfAbsent[*lsfSignature]()
}

func lsfFromNativeComplexity(n Complexity) *lsfComplexity {
	return &lsfComplexity{lsfFromNativeMaybeText(n.Time), lsfFromNativeMaybeText(n.Space), lsfFromNativeComplexityMethod(n.Method)}
}

func lsfFromNativeTypeParam(n TypeParam) *lsfTypeParam {
	return &lsfTypeParam{lsfFromNativeText(n.Name), lsfFromNativeText(n.Constraint)}
}

func lsfFromNativeGroupDetails(n GroupDetails) *lsfGroupDetails {
	return &lsfGroupDetails{lsfFromNativeListArm(n.Arms), lsfFromNativeListInner(n.ElseBody), lsfFromNativeBool(n.HasElse)}
}

func lsfToValueMaybeSignature(x lsfMaybe[*lsfSignature]) LawSpecValue {
	if x.ok {
		return lsfDataValue("Maybe assayxport.contract::type::Signature", "Maybe::Present", lsfToValueSignature(x.v))
	}
	return lsfDataValue("Maybe assayxport.contract::type::Signature", "Maybe::Absent")
}

func lsfToValueComplexity(x *lsfComplexity) LawSpecValue {
	return lsfDataValue("assayxport.contract::type::Complexity", "assayxport.contract::type::Complexity::Complexity", lsfToValueMaybeText(x.fTime), lsfToValueMaybeText(x.fSpace), lsfToValueComplexityMethod(x.fMethod))
}

func lsfToValueTypeParam(x *lsfTypeParam) LawSpecValue {
	return lsfDataValue("assayxport.contract::type::TypeParam", "assayxport.contract::type::TypeParam::TypeParam", lsfToValueText(x.fName), lsfToValueText(x.fConstraint))
}

func lsfToValueGroupDetails(x *lsfGroupDetails) LawSpecValue {
	return lsfDataValue("lawspec::structural::record::0da2e14ca58604b3fe86a7b98c18b8fc5d80c0dfa11517770dd5008b6ef149d5", "lawspec::structural::record::0da2e14ca58604b3fe86a7b98c18b8fc5d80c0dfa11517770dd5008b6ef149d5::Record", lsfToValueListArm(x.fArms), lsfToValueListInner(x.fElseBody), lsfToValueBool(x.fHasElse))
}

func lsfToNativeMaybeSignature(x lsfMaybe[*lsfSignature]) LawSpecMaybe[Signature] {
	if x.ok {
		return LawSpecPresent[Signature](lsfToNativeSignature(x.v))
	}
	return LawSpecAbsent[Signature]()
}

func lsfToNativeComplexity(x *lsfComplexity) Complexity {
	return Complexity{lsfToNativeMaybeText(x.fTime), lsfToNativeMaybeText(x.fSpace), lsfToNativeComplexityMethod(x.fMethod)}
}

func lsfToNativeTypeParam(x *lsfTypeParam) TypeParam {
	return TypeParam{lsfToNativeText(x.fName), lsfToNativeText(x.fConstraint)}
}

func lsfToNativeGroupDetails(x *lsfGroupDetails) GroupDetails {
	return GroupDetails{lsfToNativeListArm(x.fArms), lsfToNativeListInner(x.fElseBody), lsfToNativeBool(x.fHasElse)}
}

