func lsfEqualBool(a, b bool) bool {
	return a == b
}

func lsfEqualListDecl(a, b *lsfList[*lsfDecl]) bool {
	return lsfEqList(a, b, lsfEqualDecl)
}

func lsfEqualComplexityMethod(a, b lsfComplexityMethod) bool {
	switch x := a.(type) {
	case *lsfComplexityMethod_Deferred:
		_, ok := b.(*lsfComplexityMethod_Deferred)
		return ok && true
	case *lsfComplexityMethod_LoopNesting:
		_, ok := b.(*lsfComplexityMethod_LoopNesting)
		return ok && true
	case *lsfComplexityMethod_Recursive:
		_, ok := b.(*lsfComplexityMethod_Recursive)
		return ok && true
	case *lsfComplexityMethod_MethodOther:
		y, ok := b.(*lsfComplexityMethod_MethodOther)
		return ok && true && x.fValue == y.fValue
	}
	return false
}

func lsfEqualInvocation(a, b *lsfInvocation) bool {
	if a == b {
		return true
	}
	return true && a.fKind == b.fKind && a.fHow == b.fHow
}

